def transform(grid):
 g=[r[:] for r in grid]
 for i,row in enumerate(g):
  for j,x in enumerate(row):
   if x==0:
    if i<2: g[i][j]=1
    elif i==2: g[i][j]=4
    elif j<2: g[i][j]=1
    elif j==2: g[i][j]=4
    else:
     cand=[row[k] for k in range(3,len(row)) if k%5==j%5 and row[k]!=0]
     g[i][j]=cand[0] if cand else 1
 return g
